import {refineLayout,selectSection,paginateTables} from './fidelity.js';
import {initMotion} from './motion.js';
import { screens,projects as archiveProjects } from './data.js';
import { S,esc,icon,link,button,roles,roleHome,screenMap,field,select,brand,date,imageFile,accountControl,name } from './ui.js';
import { publicPages,archiveItems } from './public.js';
import { accountPages,currentProject } from './account.js';
import { adminPages,contentTable } from './admin.js';
const pages={...publicPages,...accountPages,...adminPages};
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),dialogBody=document.querySelector('#dialog-body');
let route='home',timer=null,sequence=0,toastTimer=null,slide=0,contentMode=0;
const needed={dashboard:'participant',profile:'participant',mentor:'participant',security:'participant','test-intro':'participant',test:'participant','test-result':'participant',achievements:'participant',submit:'participant',project:'participant','project-results':'participant',defense:'participant',teacher:'teacher',expert:'expert',evaluation:'expert',ranking:'commission',admin:'admin',content:'admin',settings:'admin',questions:'admin',users:'admin',distribution:'admin',mailing:'admin',analytics:'admin'};
export async function api(path,data){const res=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const json=await res.json();if(!res.ok)throw Error(json.error||'Ошибка запроса');return json;}
async function refresh(){Object.assign(S,await api('bootstrap'));}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function modal(html){dialogBody.innerHTML=html;if(!dialog.open)dialog.showModal();dialogBody.querySelector('input,button,a')?.focus();}
function close(){if(dialog.open)dialog.close();dialogBody.replaceChildren();}
async function go(id){const hash='#/'+id;if(location.hash!==hash)history.pushState(null,'',hash);await render();}
function formError(form,e){const el=form.querySelector('.form-error');if(el)el.textContent=e.message;else toast(e.message);}
function values(form){return Object.fromEntries(new FormData(form));}
function counters(){document.querySelectorAll('[data-counter]').forEach(el=>{const target=document.querySelector(`[data-counter-for="${el.name}"]`);if(target)target.textContent=el.value.length+'/'+el.dataset.counter;});}
async function render(){
 const key=++sequence;clearInterval(timer);close();
 const [path,query='']=location.hash.replace(/^#\/?/,'').split('?');route=path||'home';const params=new URLSearchParams(query);if(params.get('id'))S.selectedProject=params.get('id');
 try{await refresh();if(key!==sequence)return;
 const screen=screens.find(x=>x.id===route);document.title=(screen?.title||'Страница не найдена')+' — Арктика';
 const required=needed[route];if(required&&S.user?.role!==required&&!(required==='commission'&&S.user?.role==='admin')){
  app.innerHTML=publicPages.login();const container=app.querySelector('.auth-content');container.insertAdjacentHTML('afterbegin',`<div class="notice" style="margin-bottom:25px">${S.user?'Для этого экрана требуется роль «'+roles[required]+'».':'Войди, чтобы открыть этот раздел.'}</div>`);
 }else app.innerHTML=pages[route]?pages[route](params):`<main id="main" class="container"><h1>Страница не найдена</h1><p>Проверь адрес или вернись к своему маршруту.</p>${link('home','На главную →','btn primary')}</main>`;
 const cms=S.pages?.find(p=>p.route===route);if(cms&&!cms.published&&S.user?.role!=='admin')app.innerHTML=`<main id="main" class="container"><h1>Страница не опубликована</h1>${link('home','На главную →','btn primary')}</main>`;else if(cms?.custom){const title=app.querySelector('main h1');if(title)title.textContent=cms.title;if(cms.text){const target=app.querySelector('.hero-banner p,.home-copy .lead');if(target)target.textContent=cms.text;else app.querySelector('main')?.insertAdjacentHTML('beforeend',`<article class="container"><p>${esc(cms.text)}</p></article>`);}}
 if(!pages[route]&&cms&&(cms.published||S.user?.role==='admin'))app.innerHTML=`<main id="main" class="container">${brand()}<h1>${esc(cms.title)}</h1><p>${esc(cms.text)}</p></main>`;
 if(route==='verify'){try{const certificate=await api('certificate-info?id='+encodeURIComponent(params.get('id')||''));if(key!==sequence)return;app.innerHTML=`<main id="main" class="container">${brand()}<div class="card" style="max-width:700px;margin:40px auto"><h1>Сертификат действителен</h1><p>«Удивительная и неизведанная Арктика»</p><h2>${esc(certificate.name)}</h2><p>Номер: ${esc(certificate.number)}<br>Дата: ${date(certificate.date)}<br>Результат: ${certificate.percent}%</p><small>Проверка документа локального демонстрационного конкурса. Персональные контакты не публикуются.</small></div></main>`;document.title='Проверка сертификата — Арктика';}catch{app.innerHTML=`<main id="main" class="container">${brand()}<h1 style="margin-top:40px">Сертификат не найден</h1><p>Проверь ссылку или номер документа.</p></main>`;}}
 if(route==='content')contentMode=0;
 const authContent=app.querySelector('.auth-content');if(S.user&&authContent)authContent.insertAdjacentHTML('afterbegin',`<div class="auth-current-account">${accountControl()}</div>`);
 refineLayout(route);
 if(new URLSearchParams(location.search).has('dev'))app.insertAdjacentHTML('beforeend',`<button class="all-screens" data-action="screens" aria-label="Все 40 экранов" title="Все 40 экранов">${icon('grid')}</button>`);counters();if(route==='evaluation'){const saved=S.evaluations?.find(e=>e.project===currentProject()?.id);if(saved){saved.scores.forEach((score,i)=>{const input=document.querySelector('[name="score-'+i+'"]');if(input)input.value=score;});const comment=document.querySelector('[name="comment"]');if(comment)comment.value=saved.comment;}}updateEvaluation();if(route==='teacher'&&params.get('view')){if(params.get('view')==='certificate')modal('<h2>Сертификат педагога</h2><p>Сертификат появится после завершения участия ваших учеников.</p>');else document.querySelectorAll('.workspace-content .card')[0]?.scrollIntoView();}
 if(route==='test'&&S.attempt&&!S.attempt.finished){const tick=async()=>{const remaining=Math.max(0,Math.ceil((S.attempt.deadline-Date.now())/1000));const el=document.querySelector('[data-timer]');if(el)el.textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(remaining===0){clearInterval(timer);await refresh();go('test-result');}};tick();timer=setInterval(tick,1000);}
 window.scrollTo(0,0);
 }catch(e){if(key!==sequence)return;app.innerHTML=`<main id="main" class="container"><h1>Не удалось загрузить страницу</h1><p>${esc(e.message)}</p>${button('Повторить','retry','primary')}</main>`;}
}
function demoModal(){modal(`<h2>Демонстрационные аккаунты</h2><p>Выбери роль для проверки сайта.</p><div class="spaced">${Object.entries(roles).map(([r,label])=>button(label+' →','demo-login','wide',`data-role="${r}"`)).join('')}</div><p><small>Демо-пароль: Arctic2026!<br>Адрес: название роли на английском @arctic.demo</small></p>`);}
function accountMenu(){if(!S.user)return go('login');modal(`<h2>Аккаунт</h2><p><strong>${esc(name())}</strong><br>${esc(S.user.email)}<br><small>${roles[S.user.role]}</small></p><div class="spaced account-actions">${link(roleHome(S.user.role),'Мой кабинет →','btn wide')}${S.user.role==='participant'?link('profile','Мой профиль','btn wide'):button('Мой профиль','account-profile','wide')}${button('Сменить аккаунт','account-switch','wide')}${button('Выйти','logout','wide danger')}</div>`);}
function accountProfile(){if(!S.user)return go('login');if(S.user.role==='participant')return go('profile');modal(`<h2>Мой профиль</h2><dl class="data-list account-details">${[['ФИО',name()],['Email',S.user.email],['Роль',roles[S.user.role]],['Школа',S.user.profile.school],['Регион',S.user.profile.region]].filter(([,value])=>value).map(([label,value])=>`<dt>${label}</dt><dd>${esc(value)}</dd>`).join('')}</dl>${button('Изменить данные','edit-profile','wide')}`);}
function switchAccount(){modal(`<h2>Сменить аккаунт</h2><p>Введи данные другого аккаунта. Текущий вход сохранится, если пароль окажется неверным.</p><form data-form="login">${field('Email','email','','email','required autocomplete="username"')}${field('Пароль','password','','password','required autocomplete="current-password"')}<p class="form-error" role="alert"></p><button type="submit" class="btn primary wide">Войти</button></form><div class="separator">или</div>${button('Выбрать демо-аккаунт','demo','wide sm')}`);}
function updateEvaluation(){const inputs=[...document.querySelectorAll('[data-weight]')];if(!inputs.length)return;let total=0;inputs.forEach((el,i)=>{const weighted=Number(el.value)*Number(el.dataset.weight)/100;total+=weighted;const out=document.querySelector(`[data-weighted="${i}"]`);if(out)out.textContent=weighted.toFixed(2);});const target=document.querySelector('[data-evaluation-total]');if(target)target.textContent=total.toFixed(2).replace('.',',');}
async function answer(next,finish=false){const a=S.attempt;if(!a||a.finished)return;const input=document.querySelector('input[name="answer"]:checked');if(!input&&!finish&&next>a.index)throw Error('Выберите вариант ответа');const result=await api('test-answer',{id:a.id,index:a.index,answer:input?Number(input.value):a.answers[a.index],next,finish});S.attempt=result.attempt;if(result.attempt.finished)go('test-result');else await render();}
function projectModal(p){if(!p)return toast('Проект не найден');modal(`<h2>${esc(p.name)}</h2><p>${esc(p.annotation)}</p><p>Автор: ${esc(p.author)}</p><p>Статус: ${esc(p.status)}</p>${S.user?.role==='admin'?button('Назначить эксперта','assign','mint',`data-id="${p.id}"`):''}<div style="margin-top:15px">${p.files?.map(f=>`<a class="btn sm" href="/api/files/${f.id}">${esc(f.name)} ${icon('download')}</a>`).join('')||'Файлы ещё не загружены'}</div>`);}
const actions={
 'nav-tab':el=>{el.closest('nav')?.querySelectorAll('[data-action="nav-tab"]').forEach(b=>b.classList.toggle('active',b===el));document.querySelector(`.tab[data-key="${el.dataset.navKey}"][data-tab="${el.dataset.navTab}"]`)?.click();},
 'nav-focus':el=>{const target=document.querySelector(el.dataset.selector);target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});target?.focus();},
 'region-list':()=>groupedUsers('Регионы участников','region'),
 'school-list':()=>groupedUsers('Школы участников','school'),
 'nomination-list':()=>modal(`<h2>Номинации проектов</h2><div class="spaced">${[...new Set(S.projects.map(p=>p.nomination))].map(n=>`<div class="card"><strong>${esc(n)}</strong><p>${S.projects.filter(p=>p.nomination===n).length} проектов</p></div>`).join('')||'<p>Проектов пока нет.</p>'}</div>`),
 'teacher-projects':()=>modal(`<h2>Проекты учеников</h2><div class="spaced">${S.projects.map(p=>button(esc(p.name)+' →','project-details','wide',`data-id="${p.id}"`)).join('')||'<p>Проектов пока нет.</p>'}</div>`),
 'expert-comments':()=>modal(`<h2>Мои рекомендации</h2><div class="spaced">${S.evaluations.map(e=>`<div class="card"><h3>${esc(S.projects.find(p=>p.id===e.project)?.name||'Проект')}</h3><p>${esc(e.comment||'Комментарий не добавлен')}</p></div>`).join('')||'<p>После оценки проекта здесь появятся ваши рекомендации.</p>'}</div>`),
 'question-stats':()=>modal(`<h2>Статистика банка вопросов</h2><p>Всего: ${S.questions.length}<br>Опубликовано: ${S.questions.filter(q=>q.published).length}<br>Черновиков: ${S.questions.filter(q=>!q.published).length}</p>`),
 menu:el=>{const nav=document.querySelector('.topnav');nav?.classList.toggle('open');el.setAttribute('aria-expanded',nav?.classList.contains('open')?'true':'false');},
 retry:render,screens:()=>modal(screenMap()),demo:demoModal,
 'demo-login':async el=>{await api('login',{email:el.dataset.role+'@arctic.demo',password:'Arctic2026!'});await refresh();await go(roleHome(S.user.role));},
 account:accountMenu,'account-profile':accountProfile,'account-switch':switchAccount,
 logout:async()=>{await api('logout',{});await go('home');},
 password:el=>{const input=document.getElementById(el.dataset.target);if(input){input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Показать пароль':'Скрыть пароль');}},
 'register-role':el=>{const form=el.closest('form');form.elements.role.value=el.dataset.role;form.querySelectorAll('.role-card').forEach(x=>x.classList.toggle('selected',x===el));const checkbox=form.elements.parentConsent;checkbox.required=el.dataset.role==='participant';form.querySelector('[data-parent-consent]').hidden=!checkbox.required;},
 code:async el=>{const form=el.closest('form'),email=form.elements.email.value;const result=await api('register-code',{email});modal(`<h2>Локальный почтовый ящик</h2><p>Доставка внешней почты не подключена. Для проверки регистрации используй этот одноразовый код:</p><div style="font-size:40px;letter-spacing:6px;color:var(--mint)">${esc(result.code)}</div><p>Действителен 10 минут.</p>`);},
 integration:el=>modal(`<h2>${esc(el.dataset.service||'VK ID')}</h2><p>Сервис не подключён. Внешние API требуют настроек владельца и серверных ключей.</p><p>Локальная версия не отправляет реальные письма, push-сообщения и не создаёт видеовстречи.</p>`),
 forgot:()=>modal(`<h2>Восстановление доступа</h2><form data-form="forgot">${field('Email','email','','email','required')}<p class="form-error" role="alert"></p><button class="btn primary wide">Получить ссылку</button></form><p><small>В локальном режиме письмо находится в демонстрационном почтовом ящике.</small></p>`),
 'scroll-route':()=>document.querySelector('#route')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}),
 'scroll-section':selectSection,
 image:el=>modal(`<img class="modal-image" src="${esc(imageFile(el.dataset.image))}" alt="Арктика">`),
 video:()=>modal(`<h2>Почувствуй Арктику</h2><div class="arctic-film"><img src="assets/hero.webp" alt="Арктическая сцена с белым медведем"><div class="film-caption">Удивительная и неизведанная Арктика</div></div><p>В исходных материалах видео отсутствует. Здесь показана анимированная обложка; видео можно подключить в CMS.</p>`),
 'archive-detail':el=>{const p=archiveItems().find(p=>p.id===el.dataset.id);if(p)modal(`<h2>${esc(p.name)}</h2>${photoSafe(p.image)}<p>Номинация: ${esc(p.nomination)} · ${esc(p.year)}</p><p>Автор: ${esc(p.author)}</p><p>${esc(p.annotation||'Демонстрационная работа из архива конкурса. Приватные файлы участника здесь не публикуются.')}</p>`);},
 'history-result':()=>modal(`<h2>Итоги конкурса</h2><p>4 200 участников · 78 регионов · 312 проектов</p><p>Демонстрационная статистика из исходного макета.</p>${link('archive','Смотреть проекты →','btn mint')}`),
 'edit-profile':()=>{const p=S.user.profile;modal(`<h2>Изменить профиль</h2><form data-form="profile"><div class="form-grid">${field('ФИО *','name',p.name,'text','required maxlength="200"')}${field('Дата рождения','birth',p.birth||'','date')}${field('Класс','grade',p.grade||'','number','min="1" max="11"')}${field('Школа','school',p.school)}${field('Регион','region',p.region)}${field('ФИО представителя','parent',p.parent)}${field('Телефон','phone',p.phone,'tel')}${field('Email представителя','parentEmail',p.parentEmail,'email')}</div><p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить</button></form>`);},
 'cancel-invite':async el=>{await api('mentor-answer',{id:el.dataset.id,accept:false});await render();toast('Приглашение отменено');},
 'accept-invite':async el=>{await api('mentor-answer',{id:el.dataset.id,accept:true});await render();toast('Приглашение принято');},
 'teacher-invite':()=>modal(`<h2>Пригласить ученика</h2><p>Попросите ученика в разделе «Мой руководитель» указать ваш email:</p><strong>${esc(S.user.email)}</strong><p>После отправки вы сможете принять приглашение здесь.</p>`),
 'change-email':()=>modal(`<h2>Изменить email</h2><form data-form="email-change">${field('Новый email','email','','email','required')}${field('Текущий пароль','currentPassword','','password','required')}<p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить</button></form>`),
 'change-password':()=>modal(`<h2>Изменить пароль</h2><form data-form="password-change">${field('Текущий пароль','currentPassword','','password','required')}${field('Новый пароль','password','','password','required minlength="8" maxlength="128"')}<p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить пароль</button></form>`),
 notifications:()=>modal(`<h2>Уведомления</h2><p>Открыт образовательный этап конкурса. Пройди тест и подготовь проект.</p>${link('test-intro','Перейти к тесту →','btn mint')}`),
 messages:()=>modal(`<h2>Сообщения</h2>${S.messages.length?S.messages.map(m=>`<div class="card"><p>${esc(m.message)}</p><small>${date(m.date)}</small></div>`).join(''):'<p>Новых сообщений пока нет.</p>'}`),
 message:el=>modal(`<h2>Новое сообщение</h2><form data-form="message"><input type="hidden" name="to" value="${esc(el.dataset.to||'admin')}"><input type="hidden" name="project" value="${esc(el.dataset.project||'')}">${field('Сообщение','message','','textarea','required maxlength="2000"')}<p class="form-error" role="alert"></p><button class="btn mint wide">Отправить</button></form>`),
 'test-tips':()=>modal(`<h2>Советы по прохождению</h2><p>Внимательно читай вопросы. Выбери один вариант ответа, используй «Назад» для проверки. Таймер продолжает идти при обновлении страницы. При завершении времени попытка закончится автоматически.</p>${link('explore','Изучить материалы →','btn mint')}`),
 'test-back':()=>answer(Math.max(0,S.attempt.index-1)),
 share:async()=>{const text=location.origin+'/#/verify?id='+S.attempt.id;try{await navigator.clipboard.writeText(text);toast('Ссылка для проверки сертификата скопирована');}catch{modal(`<h2>Ссылка</h2><input class="control" value="${esc(text)}" readonly>`);}},
 'copy-defense':()=>toast('Встреча ещё не назначена. Ссылка появится после подключения видеосервиса'),
 'meeting-check':()=>modal(`<h2>Тестовое подключение</h2><p>Сервис видеовстреч не подключён. Проверь камеру и микрофон в приложении видеосвязи, которым будет пользоваться организатор.</p>`),
 'project-details':el=>projectModal(S.projects.find(p=>p.id===el.dataset.id)),
 evaluate:el=>{S.selectedProject=el.dataset.id;go('evaluation?id='+el.dataset.id);},
 admit:async el=>{await api('admin-project',{id:el.dataset.id,action:'admit'});await render();toast('Проект допущен');},
 reject:el=>modal(`<h2>Отклонить проект</h2><form data-form="reject"><input type="hidden" name="id" value="${el.dataset.id}">${field('Причина *','reason','','textarea','required')}<p class="form-error" role="alert"></p><button class="btn danger">Отклонить</button></form>`),
 assign:el=>modal(`<h2>Назначить эксперта</h2><form data-form="assign"><input type="hidden" name="id" value="${el.dataset.id}"><div class="field"><label for="expert">Эксперт</label><select id="expert" name="expert">${S.users.filter(u=>u.role==='expert').map(u=>`<option value="${u.id}">${esc(u.profile.name)}</option>`).join('')}</select></div><p class="form-error" role="alert"></p><button class="btn mint">Назначить</button></form>`),
 'publish-results':async()=>{const eligible=S.projects.filter(p=>p.reviews?.length&&!p.published);if(!eligible.length)return toast('Нет новых оценённых проектов для публикации');for(const p of eligible)await api('admin-project',{id:p.id,action:'publish'});await render();toast('Результаты опубликованы');},
 'block-user':async el=>{await api('admin-user',{id:el.dataset.id,blocked:el.dataset.blocked==='1'});await render();toast('Статус пользователя изменён');},
 'new-content':()=>contentMode===0?pageModal():contentModal(),
 'edit-content':el=>el.dataset.kind==='page'?pageModal(S.pages.find(n=>n.id===el.dataset.id)):contentModal(S.news.find(n=>n.id===el.dataset.id)),
 'select-question':async el=>{S.selectedQuestion=el.dataset.id;await render();},
 'new-question':()=>{S.selectedQuestion='new';modal(`<h2>Добавить вопрос</h2><form data-form="question">${field('Текст вопроса','q','','textarea','required')}${select('Тема','topic',['Природа Арктики','Научные исследования','Люди Севера','Будущее Арктики'])}${[0,1,2,3].map(i=>field('Вариант '+(i+1),'a-'+i,'','text','required')).join('')}${select('Правильный вариант (0–3)','correct',[0,1,2,3])}<label class="checkbox"><input name="published" type="checkbox" checked>Опубликован</label><p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить вопрос</button></form>`);},
 'question-filter':()=>filterItems(),
 'user-role-tab':el=>{document.querySelectorAll('[data-action="user-role-tab"]').forEach(b=>b.classList.toggle('active',b===el));document.querySelectorAll('[data-item]').forEach(row=>row.hidden=!!el.dataset.role&&row.dataset.category!==el.dataset.role);paginateTables(true);},
 'reset-filters':()=>{document.querySelectorAll('select').forEach(s=>s.selectedIndex=0);document.querySelectorAll('[data-search]').forEach(i=>i.value='');filterItems();},
 'add-stage':()=>modal(`<h2>Добавить этап</h2><form data-form="stage">${field('Название','title','','text','required maxlength="100"')}<p class="form-error" role="alert"></p><button class="btn mint">Добавить</button></form>`),
 'add-user':()=>modal(`<h2>Добавить пользователя</h2><p>Публичная регистрация доступна для участника и педагога. Новый эксперт или администратор добавляется только администратором.</p><form data-form="admin-add-user">${field('ФИО','name','','text','required')}${field('Email','email','','email','required')}${select('Роль','role',['participant','teacher','expert','commission','admin'])}${field('Временный пароль','password','','password','required minlength="8"')}<p class="form-error" role="alert"></p><button class="btn mint wide">Создать</button></form>`),
 'admin-create-project':()=>modal(`<h2>Создать проект</h2><form data-form="admin-create-project">${field('Название','name','','text','required maxlength="200"')}${select('Номинация','nomination',['Экология','Биология','География','Технологии','История'])}<div class="field"><label for="owner">Участник</label><select id="owner" name="owner">${S.users.filter(u=>u.role==='participant').map(u=>`<option value="${u.id}">${esc(u.profile.name)}</option>`).join('')}</select></div><p class="form-error" role="alert"></p><button class="btn mint wide">Создать черновик</button></form>`),
 channel:el=>{const form=el.closest('form');form.elements.channel.value=el.dataset.channel;form.querySelectorAll('.channel-options button').forEach(b=>b.classList.toggle('active',b===el));},
 slide:el=>setSlide(Number(el.dataset.slideIndex)),
 'slide-next':()=>setSlide((slide+1)%4),
 'slide-prev':()=>setSlide((slide+3)%4)
};
function groupedUsers(title,key){const counts=new Map();for(const u of S.users.filter(u=>u.role==='participant')){const value=u.profile[key]||'Не указано';counts.set(value,(counts.get(value)||0)+1);}modal(`<h2>${title}</h2><div class="spaced">${[...counts].sort((a,b)=>b[1]-a[1]).map(([label,total])=>`<div class="setting-row"><span>${esc(label)}</span><strong>${total}</strong></div>`).join('')||'<p>Участников пока нет.</p>'}</div>`);}
function photoSafe(name){return `<img class="modal-image" src="assets/${esc(name)}.webp" alt="Арктика">`;}
function contentModal(n){modal(`<h2>${n?'Редактировать':'Создать'} новость</h2><form data-form="content"><input type="hidden" name="id" value="${n?.id||''}">${field('Заголовок','title',n?.title||'','text','required maxlength="200"')}${field('Текст','text',n?.text||'','textarea','required maxlength="10000"')}${select('Категория','category',['Новости','Анонсы','Итоги'],n?.category)}${select('Изображение','image',['mountain','bear','ship','aurora','iceberg'],n?.image)}<label class="checkbox"><input type="checkbox" name="published" ${n?.published?'checked':''}>Опубликовано</label><p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить</button></form>`);}
function pageModal(p){modal(`<h2>${p?'Редактировать':'Создать'} страницу</h2><form data-form="page"><input type="hidden" name="id" value="${p?.id||''}">${field('Заголовок','title',p?.title||'','text','required maxlength="200"')}${field('Адрес (латиница)','route',p?.route||'','text','required pattern="[a-z0-9-]+"')}${field('Вводный текст','text',p?.text||'','textarea','maxlength="10000"')}<label class="checkbox"><input type="checkbox" name="published" ${p?.published?'checked':''}>Опубликовано</label><p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить</button></form>`);}
function setSlide(i){slide=i;const pics=['bear','iceberg','whale','ice'];const view=document.querySelector('.presentation-preview');if(view)view.style.backgroundImage=`linear-gradient(90deg,#0d385ace,#0d385a11),url('assets/${pics[i]}.webp')`;document.querySelectorAll('[data-slide-index]').forEach(b=>b.classList.toggle('active',Number(b.dataset.slideIndex)===i));const label=document.querySelector('[data-slide]');if(label)label.textContent=(i+1)+' / 4';}
const forms={
 login:async(f,v)=>{await api('login',v);await refresh();await go(needed[route]===S.user.role?route:roleHome(S.user.role));},
 register:async(f,v)=>{if(v.password!==v.repeat)throw Error('Пароли не совпадают');await api('register',{...v,consent:!!v.consent,parentConsent:!!v.parentConsent});await refresh();go(roleHome(S.user.role));toast('Регистрация завершена');},
 contact:async(f,v)=>{const r=await api('contact',v);f.reset();toast(r.message);},
 profile:async(f,v)=>{await api('profile',v);await render();toast('Профиль сохранён');},
 mentor:async(f,v)=>{await api('mentor',v);await render();toast('Приглашение создано');},
 'email-change':async(f,v)=>{await api('email-change',v);await render();toast('Email изменён в локальном режиме');},
 'password-change':async(f,v)=>{await api('profile',v);await render();toast('Пароль изменён');},
 'test-start':async(f,v)=>{await api('test-start',{count:Number(v.count),minutes:Number(v.minutes)});go('test');await render();},
 'test-answer':async()=>answer(S.attempt.index+1,S.attempt.index===S.attempt.bank.length-1),
 project:async(f,v,submitter)=>{if(submitter?.value==='submit'){if(!v.name.trim()||v.nomination==='Выберите номинацию'||!v.annotation.trim())throw Error('Заполните название, номинацию и аннотацию');if(!currentProject()?.files?.some(f=>f.kind==='research'))throw Error('Загрузите основной файл исследования');}const r=await api('project',{...v,submit:submitter?.value==='submit'});S.selectedProject=r.project.id;go('project?id='+r.project.id);await render();toast(r.project.status==='Черновик'?'Черновик сохранён':'Проект отправлен на проверку');},
 evaluation:async(f,v,submitter)=>{const scores=S.config.criteria.map((_,i)=>Number(v['score-'+i]));const r=await api('evaluation',{project:v.project,scores,comment:v.comment,submit:submitter?.value==='submit'});toast((submitter?.value==='submit'?'Оценка отправлена: ':'Черновик оценки сохранён: ')+r.score.toFixed(2));},
 message:async(f,v)=>{await api('message',v);close();await refresh();toast('Сообщение сохранено');},
 reject:async(f,v)=>{await api('admin-project',{...v,action:'reject'});await render();toast('Проект отклонён');},
 assign:async(f,v)=>{await api('admin-project',{...v,action:'assign'});await render();toast('Эксперт назначен');},
 content:async(f,v)=>{await api('admin-save',{kind:'news',id:v.id||undefined,data:{...v,published:!!v.published}});await render();toast('Новость сохранена');},
 page:async(f,v)=>{await api('admin-page',{...v,published:!!v.published});await render();toast('Страница сохранена');},
 question:async(f,v)=>{await api('admin-save',{kind:'questions',id:v.id||undefined,data:{q:v.q,a:[v['a-0'],v['a-1'],v['a-2'],v['a-3']],correct:Number(v.correct),topic:v.topic,published:!!v.published,difficulty:'Средний'}});await render();toast('Вопрос сохранён');},
 settings:async(f,v)=>{if(v.start>v.end)throw Error('Дата начала позже даты окончания');const config={...S.config,stages:[v.stage,...S.config.stages.slice(1)],status:v.status,start:v.start,end:v.end,description:v.description};await api('admin-save',{kind:'config',data:config});await render();toast('Настройки сохранены');},
 stage:async(f,v)=>{await api('admin-save',{kind:'config',data:{...S.config,stages:[...S.config.stages,v.title]}});await render();toast('Этап добавлен');},
 mailing:async(f,v)=>{await api('admin-save',{kind:'mailings',data:v});toast('Демо-рассылка сохранена. Внешние сообщения не отправлялись');await refresh();},
 report:async(f,v)=>{location.href='/api/report?format='+(v.format.startsWith('Excel')?'xlsx':'csv');},
 forgot:async(f,v)=>{const r=await api('forgot',v);modal(`<h2>Локальный почтовый ящик</h2><p>${esc(r.message)}</p>${r.token?`<form data-form="reset-password"><input type="hidden" name="token" value="${r.token}">${field('Новый пароль','password','','password','required minlength="8"')}<p class="form-error" role="alert"></p><button class="btn mint">Установить пароль</button></form>`:''}`);},
 'reset-password':async(f,v)=>{await api('reset-password',v);close();toast('Пароль изменён. Войдите с новым паролем');},
 'admin-add-user':async(f,v)=>{await api('admin-add-user',v);await render();toast('Пользователь создан');},
 'admin-create-project':async(f,v)=>{await api('admin-create-project',v);await render();toast('Черновик проекта создан');},
 criteria:async(f,v)=>{const criteria=S.config.criteria.map(([t],i)=>[t,Number(v['weight-'+i])]);await api('admin-save',{kind:'config',data:{...S.config,criteria}});await render();toast('Критерии сохранены');}
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();const action=actions[el.dataset.action];if(!action)return toast('Действие недоступно');el.disabled=true;try{await action(el);}catch(err){toast(err.message);}finally{el.disabled=false;}}else if(e.target.closest('a[href^="#/"]'))close();const tab=e.target.closest('[data-tab]');if(tab){e.preventDefault();onTab(tab);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const handler=forms[form.dataset.form];if(!handler)return;const buttons=[...form.querySelectorAll('button[type="submit"],button:not([type])')];buttons.forEach(b=>b.disabled=true);form.querySelectorAll('.form-error').forEach(el=>el.textContent='');try{await handler(form,values(form),e.submitter);}catch(err){formError(form,err);}finally{buttons.forEach(b=>b.disabled=false);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.matches('[data-setting]')){const notifications=S.user.profile.notifications||[false,false,false];notifications[Number(el.dataset.setting)]=el.checked;try{await api('profile',{notifications});toast('Настройка сохранена');}catch(err){toast(err.message);el.checked=!el.checked;}}if(el.matches('[data-filter],[name="question-topic"],[name="question-difficulty"],[name="question-status"],[name="user-role"],[name="user-status"]'))filterItems();if(el.matches('[data-upload]')){try{await uploadFile(el);}catch(err){toast(err.message);el.value='';}}});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]'))filterItems();if(e.target.matches('[data-counter]'))counters();if(e.target.matches('[data-weight]'))updateEvaluation();if(e.target.matches('[data-email-title]'))document.querySelector('[data-email-preview-title]').textContent=e.target.value;if(e.target.matches('[data-email-text]'))document.querySelector('[data-email-preview-text]').textContent=e.target.value;});
async function uploadFile(input){const file=input.files?.[0];if(!file)return;const kind=input.dataset.upload;const limit=S.deployment.maxUploadBytes??(kind==='research'?20e6:50e6);if(file.size>limit)throw Error('Максимальный размер файла: '+(limit/1e6)+' МБ');toast('Загрузка файла…');let p=currentProject();if(['research','presentation','video'].includes(kind)&&!p){const form=input.closest('form'),v=values(form);p=(await api('project',{...v,name:v.name||'Новый проект',submit:false})).project;S.selectedProject=p.id;if(form.elements.id)form.elements.id.value=p.id;}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('upload',{name:file.name,data,kind,project:['research','presentation','video'].includes(kind)?p?.id:undefined});await refresh();const label=document.querySelector(`[data-file-name="${kind}"]`);if(label)label.textContent=file.name;else await render();toast('Файл загружен');}
function filterItems(){const queries=[...document.querySelectorAll('[data-search]')].map(x=>x.value.trim().toLowerCase()).filter(Boolean);const filters=[...document.querySelectorAll('[data-filter]')].filter(s=>s.selectedIndex>0).map(s=>s.value.toLowerCase());const qtopic=document.querySelector('[name="question-topic"]'),qdifficulty=document.querySelector('[name="question-difficulty"]'),qstatus=document.querySelector('[name="question-status"]');for(const s of [qtopic,qdifficulty,qstatus])if(s?.selectedIndex>0)filters.push(s.value.toLowerCase());const role=document.querySelector('[name="user-role"]'),ustatus=document.querySelector('[name="user-status"]');if(role?.selectedIndex>0)filters.push(role.value.toLowerCase());if(ustatus?.selectedIndex>0)filters.push(ustatus.value.toLowerCase());let found=0;document.querySelectorAll('[data-item]').forEach(el=>{const text=(el.textContent+' '+(el.dataset.category||'')+' '+(el.dataset.meta||'')).toLowerCase();el.hidden=!queries.every(q=>text.includes(q))||!filters.every(q=>text.includes(q));if(!el.hidden)found++;});const counter=document.querySelector('[data-found]');if(counter)counter.textContent=`Найдено ${found} материалов (демо)`;paginateTables(true);}
function onTab(tab){const bar=tab.closest('[data-tabs]')||tab.parentElement,key=tab.dataset.key,i=Number(tab.dataset.tab);bar.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('active',t===tab));
 if(key==='rules'){const layout=document.querySelector('.faq-layout');layout.querySelector('article').hidden=i===1;layout.querySelector('aside').hidden=i===1;layout.style.gridTemplateColumns=i===1?'1fr':'';}
 if(key==='history')document.querySelectorAll('[data-history-year]').forEach(t=>t.textContent=tab.textContent);
 if(['documents','news','media','distribution','teacher','achievements'].includes(key)){const category=tab.textContent.trim();document.querySelectorAll('[data-item]').forEach(el=>{const map={distribution:['','На проверке','Допущен','На экспертизе','Оценён','Отклонён'],teacher:['','Готовит проект','На проверке','Завершён']};el.hidden=i!==0&&(key==='media'?el.dataset.category!==category:key==='documents'?el.dataset.category!==category:key==='news'?el.dataset.category!==category:!el.textContent.includes(map[key]?.[i]||category));});if(key==='media'&&i===0)document.querySelectorAll('[data-item]').forEach(el=>el.hidden=el.dataset.category!=='Фотографии');if(key==='achievements'){const cert=document.querySelector('.certificate-layout');if(cert)cert.hidden=i===1;if(i===1)toast('Дипломы появятся после публикации результатов проекта');}}
 if(key==='about'){const panel=document.querySelector('[data-about-panel]');if(i>0)panel.innerHTML=`<div><h2>${esc(tab.textContent)}</h2><p>${['','Организатор конкурса уточняется. Информация будет обновлена.','Экология, биология, технологии, география и культура народов Севера.','Отборочный этап — онлайн. Финальный этап — защита проектов.','Победители и призёры получат дипломы, памятные призы и новые возможности.'][i]}</p></div><div>${link('participate','Узнать об участии →','btn mint')}</div>`;else{render();}}
 if(key==='settings'&&i===2){document.querySelector('.settings-layout').innerHTML=`<form class="card" data-form="criteria"><h3>Критерии оценки</h3>${S.config.criteria.map(([t,w],j)=>field(t+' (%)','weight-'+j,w,'number','required min="0" max="100"')).join('')}<p class="form-error" role="alert"></p><button class="btn mint">Сохранить веса</button></form><div class="card"><h3>Правила расчёта</h3><p>Сумма весов должна составлять 100%. Балл по критерию — 0…10. Итог вычисляется как сумма взвешенных баллов.</p></div>`;}else if(key==='settings'&&i>0)modal(`<h2>${esc(tab.textContent)}</h2><p>${i===1?'Экология, биология, география, технологии, культура и история.':'Текущий сезон: '+esc(S.config.season)}</p>`);
 if(key==='mailing'&&i===1)modal(`<h2>История рассылок</h2>${S.mailings.length?S.mailings.map(m=>`<div class="card"><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><small>${esc(m.status)} · ${esc(m.date)}</small></div>`).join(''):'<p>Рассылок пока нет.</p>'}`);
 if(key==='mailing'&&i===2)modal(`<h2>Шаблоны</h2><p>Приглашение в конкурс, открытие этапа, статус проекта. Выберите тему и отредактируйте текст в новой рассылке.</p>`);
 if(key==='mailing'&&i===3)actions.integration(tab);
 if(key==='content'&&i>1)modal(`<h2>${esc(tab.textContent)}</h2><p>В этом разделе используются материалы медиабиблиотеки. Загрузите файл и свяжите его с новостью.</p>`);
 if(key==='content'&&i<2){contentMode=i;document.querySelector('[data-content-table]').innerHTML=contentTable(i);const b=document.querySelector('[data-action="new-content"]');if(b)b.textContent=i===0?'＋ Новая страница':'＋ Новая новость';}
 if(key==='evaluation'&&i>0)modal(`<h2>${esc(tab.textContent)}</h2>${currentProject()?.files?.length?currentProject().files.map(f=>`<a class="btn wide" href="/api/files/${f.id}">${esc(f.name)} ${icon('download')}</a>`).join(''):'<p>Дополнительные файлы не загружены.</p>'}`);
 paginateTables(true);
}
document.querySelector('.dialog-close').addEventListener('click',close);dialog.addEventListener('close',()=>{if(!dialog.open)dialogBody.replaceChildren();});dialog.addEventListener('click',e=>{if(e.target===dialog)close();});window.addEventListener('hashchange',render);initMotion(app,dialog);await render();
